export const FULL_CUES: Cue[][] = [[{"text": "Every company has a strategy.", "start": 0.604, "end": 2.531}, {"text": "It is agreed in a workshop, presented to the board,", "start": 2.531, "end": 5.721}, {"text": "and then it meets the year.", "start": 5.721, "end": 7.427}, {"text": "The plan lives in a deck, the targets in a spreadsheet,", "start": 7.427, "end": 10.708}, {"text": "the figures in emails,", "start": 10.708, "end": 12.245}, {"text": "and every review starts from scratch.", "start": 12.245, "end": 14.953}, {"text": "The strategy is right.", "start": 14.953, "end": 16.529}, {"text": "Keeping it alive is the hard part.", "start": 16.529, "end": 19.22}], [{"text": "That is what the Strategy Management Platform is for:", "start": 0.617, "end": 3.794}, {"text": "one place for the plans, the reporting and the results,", "start": 3.794, "end": 7.245}, {"text": "for everyone who carries them.", "start": 7.245, "end": 9.055}, {"text": "This is how it works.", "start": 9.055, "end": 10.988}], [{"text": "The platform is shaped like the company.", "start": 0.617, "end": 2.987}, {"text": "The group at the top.", "start": 2.987, "end": 4.263}, {"text": "Under it, the business units,", "start": 4.263, "end": 6.411}, {"text": "each with a plan of its own.", "start": 6.411, "end": 8.13}, {"text": "Beside them, the supporting functions:", "start": 8.13, "end": 10.461}, {"text": "finance, HR, marketing, IT.", "start": 10.461, "end": 13.716}, {"text": "One row to move between them,", "start": 13.716, "end": 15.539}, {"text": "and every person lands on what is theirs.", "start": 15.539, "end": 18.764}], [{"text": "A plan starts with its foundation.", "start": 0.604, "end": 2.74}, {"text": "Who we are, what we provide, and for whom.", "start": 2.74, "end": 5.786}, {"text": "The winning aspiration, and the key objectives", "start": 5.786, "end": 8.221}, {"text": "that say what success looks like,", "start": 8.221, "end": 10.357}, {"text": "this year and by the horizon.", "start": 10.357, "end": 12.544}, {"text": "Beside it, the SWOT: strengths, weaknesses,", "start": 12.544, "end": 15.995}, {"text": "opportunities and threats.", "start": 15.995, "end": 17.974}, {"text": "Four lists, each one clear.", "start": 17.974, "end": 20.636}], [{"text": "Then the plan itself.", "start": 0.617, "end": 2.023}, {"text": "Each pillar carries its key measures,", "start": 2.023, "end": 4.341}, {"text": "with a direction and a target.", "start": 4.341, "end": 6.451}, {"text": "Under them, the tactics: what will be done,", "start": 6.451, "end": 9.38}, {"text": "the outcome it is meant to produce,", "start": 9.38, "end": 11.372}, {"text": "who owns it, and which quarters it runs in.", "start": 11.372, "end": 14.211}, {"text": "Everything a team needs to read the plan", "start": 14.211, "end": 16.62}, {"text": "is on one screen, and a reader sees all of it", "start": 16.62, "end": 19.393}, {"text": "without being able to change any of it.", "start": 19.393, "end": 22.484}], [{"text": "A supporting function plans in its own shape.", "start": 0.604, "end": 3.326}, {"text": "Its key objectives at the top.", "start": 3.326, "end": 5.266}, {"text": "Then its projects: the deliverables it hands over,", "start": 5.266, "end": 8.43}, {"text": "the outcomes they are meant to change,", "start": 8.43, "end": 10.474}, {"text": "and the milestones along the way,", "start": 10.474, "end": 12.531}, {"text": "each with an owner and a date.", "start": 12.531, "end": 15.236}], [{"text": "When a reporting cycle opens,", "start": 0.604, "end": 2.492}, {"text": "the Reporting tab turns orange.", "start": 2.492, "end": 4.888}, {"text": "The owner enters this cycle's figure", "start": 4.888, "end": 6.984}, {"text": "against every key objective,", "start": 6.984, "end": 9.055}, {"text": "and a note where a figure needs one.", "start": 9.055, "end": 11.411}, {"text": "Then each pillar in turn:", "start": 11.411, "end": 13.365}, {"text": "its key measures and its tactics,", "start": 13.365, "end": 15.917}, {"text": "each asking for the same thing, the figure so far.", "start": 15.917, "end": 19.51}, {"text": "The count at the top says how much is in.", "start": 19.51, "end": 21.893}, {"text": "Submit to the Strategy Management Office", "start": 21.893, "end": 23.924}, {"text": "stays held until everything is entered,", "start": 23.924, "end": 26.594}, {"text": "so nothing goes forward half done.", "start": 26.594, "end": 28.859}, {"text": "Save a draft and come back;", "start": 28.859, "end": 30.786}, {"text": "submit when it is complete.", "start": 30.786, "end": 33.308}], [{"text": "The moment figures are in, performance is derived.", "start": 0.617, "end": 4.055}, {"text": "Nothing is typed into a score.", "start": 4.055, "end": 6.008}, {"text": "Key objectives, pillars and execution", "start": 6.008, "end": 8.885}, {"text": "each carry a figure, coloured by band:", "start": 8.885, "end": 11.945}, {"text": "on track, needs attention, off track.", "start": 11.945, "end": 15.253}, {"text": "Every target is prorated to today,", "start": 15.253, "end": 17.544}, {"text": "so a half-year figure is measured", "start": 17.544, "end": 19.38}, {"text": "against half the year.", "start": 19.38, "end": 20.891}, {"text": "Open a pillar, and every measure", "start": 20.891, "end": 22.844}, {"text": "explains its own number.", "start": 22.844, "end": 25.22}], [{"text": "At the group, it all rolls up.", "start": 0.604, "end": 2.753}, {"text": "The group's own objectives,", "start": 2.753, "end": 4.576}, {"text": "the business units, and the supporting functions,", "start": 4.576, "end": 7.675}, {"text": "each with a figure of its own.", "start": 7.675, "end": 9.536}, {"text": "Below, where to look next:", "start": 9.536, "end": 11.711}, {"text": "every unit and function, ranked by its figure.", "start": 11.711, "end": 14.992}, {"text": "One click opens the cards, one per unit,", "start": 14.992, "end": 18.299}, {"text": "each with its objectives and its execution.", "start": 18.299, "end": 21.788}], [{"text": "For the review, the deck assembles itself", "start": 0.643, "end": 3.104}, {"text": "from the live plan: foundation, SWOT,", "start": 3.104, "end": 6.425}, {"text": "each pillar's measures and tactics,", "start": 6.425, "end": 8.625}, {"text": "with this cycle's figures already on them.", "start": 8.625, "end": 11.242}, {"text": "Present it on the projector,", "start": 11.242, "end": 12.883}, {"text": "or download it as a PDF.", "start": 12.883, "end": 15.044}, {"text": "And the Temple holds the whole strategy on one page.", "start": 15.044, "end": 19.052}], [{"text": "One platform.", "start": 0.617, "end": 1.75}, {"text": "The plan, the report and the result,", "start": 1.75, "end": 4.51}, {"text": "for everyone who carries them.", "start": 4.51, "end": 6.908}]];
